import{_ as o,c as t,o as e,ag as r}from"./chunks/framework.D6L8gzMI.js";const u=JSON.parse('{"title":"GC","description":"","frontmatter":{"title":"GC","prev":{"text":"Overview","link":"/python"},"next":{"text":"Decorator","link":"/python/decorator"}},"headers":[],"relativePath":"python/garbage-collection.md","filePath":"python/garbage-collection.md","lastUpdated":1743007343000}'),n={name:"python/garbage-collection.md"};function l(i,a,s,h,g,c){return e(),t("div",null,a[0]||(a[0]=[r('<h1 id="garbage-collection" tabindex="-1">Garbage Collection <a class="header-anchor" href="#garbage-collection" aria-label="Permalink to &quot;Garbage Collection&quot;">​</a></h1><br><p>在 Python 中，垃圾回收（GC）机制主要通过 <strong>引用计数</strong>、<strong>分代回收</strong> 和 <strong>标记-清除（Mark-and-Sweep）</strong> 三种方式来管理内存。</p><h3 id="_1-引用计数-reference-counting" tabindex="-1">1. <strong>引用计数（Reference Counting）</strong> <a class="header-anchor" href="#_1-引用计数-reference-counting" aria-label="Permalink to &quot;1. **引用计数（Reference Counting）**&quot;">​</a></h3><p>引用计数是 Python 最基本的垃圾回收机制。当一个对象被创建时，系统会为它分配一个引用计数器，用来记录有多少个地方引用该对象。每当一个引用指向该对象时，计数器增加；当一个引用不再指向该对象时，计数器减少。如果计数器为零，说明没有任何地方再引用该对象，Python 就会释放该对象占用的内存。</p><h4 id="优点" tabindex="-1"><strong>优点</strong>： <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;**优点**：&quot;">​</a></h4><ul><li>简单直接，垃圾回收的延迟较低。</li><li>对于大多数简单对象来说，效果很好。</li></ul><h4 id="缺点" tabindex="-1"><strong>缺点</strong>： <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;**缺点**：&quot;">​</a></h4><ul><li>无法处理循环引用问题，即当两个对象互相引用时，它们的引用计数永远不会为零，即使它们不再被其他地方引用。</li></ul><hr><h3 id="_2-分代回收-generational-garbage-collection" tabindex="-1">2. <strong>分代回收（Generational Garbage Collection）</strong> <a class="header-anchor" href="#_2-分代回收-generational-garbage-collection" aria-label="Permalink to &quot;2. **分代回收（Generational Garbage Collection）**&quot;">​</a></h3><p>分代回收是 Python 在引用计数的基础上引入的优化机制。对象的生命周期会被划分为不同的 &quot;代&quot;（generations）。Python 将所有对象分为三个代：</p><ul><li><strong>第0代</strong>（young generation）：新创建的对象。</li><li><strong>第1代</strong>（middle generation）：经历了一次垃圾回收的对象。</li><li><strong>第2代</strong>（old generation）：经历了多次垃圾回收的对象。</li></ul><h4 id="工作原理" tabindex="-1"><strong>工作原理</strong>： <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;**工作原理**：&quot;">​</a></h4><ul><li><strong>年轻代对象</strong>通常更容易被垃圾回收，因为它们更有可能被很快丢弃。</li><li>Python 的垃圾回收器会定期检查年轻代的对象，如果它们的引用计数降到 0，回收器会将它们从内存中清除。</li><li><strong>老年代对象</strong>不太容易被回收，因此它们会在进行垃圾回收时进行更少的检查。</li></ul><h4 id="回收过程" tabindex="-1"><strong>回收过程</strong>： <a class="header-anchor" href="#回收过程" aria-label="Permalink to &quot;**回收过程**：&quot;">​</a></h4><ul><li><strong>年轻代回收</strong>：如果第 0 代中的对象的数量达到某个阈值，回收器会对第 0 代进行垃圾回收。</li><li><strong>提升（Promotion）</strong>：如果第 0 代对象长时间存活，它们会被“提升”到第 1 代；如果它们在第 1 代存活足够长，它们会被提升到第 2 代。</li><li><strong>老年代回收</strong>：如果第 1 代和第 2 代的对象数超过阈值，Python 会进行全堆回收（包括年轻代和老年代），这通常比较消耗资源。</li></ul><h4 id="优点-1" tabindex="-1"><strong>优点</strong>： <a class="header-anchor" href="#优点-1" aria-label="Permalink to &quot;**优点**：&quot;">​</a></h4><ul><li>分代回收能提高垃圾回收的效率，因为对于年轻的对象，它们更可能是短期存在的，容易被回收，而对于存活时间较长的对象，回收频率较低。</li></ul><h4 id="缺点-1" tabindex="-1"><strong>缺点</strong>： <a class="header-anchor" href="#缺点-1" aria-label="Permalink to &quot;**缺点**：&quot;">​</a></h4><ul><li>如果有大量的短期对象存在，可能会导致垃圾回收频繁运行，影响性能。</li></ul><hr><h3 id="_3-标记-清除-mark-and-sweep" tabindex="-1">3. <strong>标记-清除（Mark-and-Sweep）</strong> <a class="header-anchor" href="#_3-标记-清除-mark-and-sweep" aria-label="Permalink to &quot;3. **标记-清除（Mark-and-Sweep）**&quot;">​</a></h3><p>标记-清除是一种常见的垃圾回收算法，Python 的垃圾回收机制也采用了这一方法。这个方法通过标记和清除两个阶段来回收内存。</p><h4 id="工作原理-1" tabindex="-1"><strong>工作原理</strong>： <a class="header-anchor" href="#工作原理-1" aria-label="Permalink to &quot;**工作原理**：&quot;">​</a></h4><ul><li><strong>标记阶段（Mark Phase）</strong>：垃圾回收器从所有活动的对象开始，递归地遍历所有对象并标记它们。如果一个对象可达（有引用指向它），则标记为“活动”对象。</li><li><strong>清除阶段（Sweep Phase）</strong>：垃圾回收器检查所有对象，如果一个对象未被标记为活动对象，则意味着它是垃圾，可以被清除，释放内存。</li></ul><h4 id="优点-2" tabindex="-1"><strong>优点</strong>： <a class="header-anchor" href="#优点-2" aria-label="Permalink to &quot;**优点**：&quot;">​</a></h4><ul><li>能够有效处理循环引用的问题，这种方式通过扫描整个对象图，标记存活的对象并清除那些不可达的对象。</li></ul><h4 id="缺点-2" tabindex="-1"><strong>缺点</strong>： <a class="header-anchor" href="#缺点-2" aria-label="Permalink to &quot;**缺点**：&quot;">​</a></h4><ul><li>标记和清除阶段的过程可能比较消耗资源，尤其是在需要回收老年代或进行全堆回收时。</li></ul><hr><h3 id="总结" tabindex="-1"><strong>总结</strong> <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**&quot;">​</a></h3><p>Python 的垃圾回收机制主要由以下三部分组成：</p><ol><li><strong>引用计数</strong>：简单、快速，但不能处理循环引用问题。</li><li><strong>分代回收</strong>：通过将对象分为不同代来优化垃圾回收，适用于大部分场景。</li><li><strong>标记-清除</strong>：用于处理循环引用，尤其是老年代回收时有效，但可能引起性能开销。</li></ol><p>Python 的垃圾回收通常结合了这三种技术，其中引用计数是基础，分代回收和标记-清除则用于优化性能和处理复杂的内存管理问题。</p>',35)]))}const b=o(n,[["render",l]]);export{u as __pageData,b as default};
